public class Solution {
    public static class Meter {
        private int units;
        private int cap;

        public Meter(int cap) {
            this.cap = cap;
            this.units = 0;
        }

        public void tick() {
            // BUG: original flaw kept — ticks past the cap, so
            // overflowed() (units == cap) can never become true
            units++;
        }

        public boolean overflowed() {
            return units == cap;
        }
    }
}

